CREATE TABLE cars (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(30) NOT NULL,price DECIMAL(10,2) NOT NULL,seats INT NOT NULL,transmission VARCHAR(30) NOT NULL,fuel VARCHAR(30) NOT NULL,badge VARCHAR(40),image_url VARCHAR(500) NOT NULL,image_file_id VARCHAR(100) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
